            op = s[pos[0]]
            pos[0] += 1
            rhs = parse_term()
            val = val + rhs if op == '+' else val - rhs
        return val

    def parse_term():
        val = parse_factor()
        while pos[0] < len(s) and s[pos[0]] in '*/':
            op = s[pos[0]]
            pos[0] += 1
            rhs = parse_factor()
            if op == '*':
                val *= rhs
            else:
                q = abs(val) // abs(rhs)
                val = q if (val >= 0) == (rhs >= 0) else -q
        return val

    def parse_factor():
        if s[pos[0]] == '(':
            pos[0] += 1
            val = parse_expr()
            pos[0] += 1
            return val
        start = pos[0]
        while pos[0] < len(s) and s[pos[0]].isdigit():
            pos[0] += 1
        return int(s[start:pos[0]])

    return parse_expr()

