def solve(s, words):
    wordset = set(words)
    maxlen = max(len(w) for w in words) if words else 0
    memo = {}

    def dfs(i):
        if i == len(s):
            return ['']
        if i in memo:
            return memo[i]
        res = []
        for j in range(i + 1, min(len(s), i + maxlen) + 1):
            w = s[i:j]
            if w in wordset:
                for rest in dfs(j):
                    res.append(w if rest == '' else w + ' ' + rest)
        memo[i] = res
        return res

    return sorted(dfs(0))

