def solve(nums, k):
    lo, hi = max(nums), sum(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        parts = 1
        cur = 0
        for x in nums:
            if cur + x > mid:
                parts += 1
                cur = x
            else:
                cur += x
        if parts <= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
